namespace ShipmentTracker.Client.Services;

public record ShipmentDto(
    int Id,
    string TrackingNumber,
    string Origin,
    string Destination,
    string Status,
    DateTime ShippedDate,
    DateTime? EstimatedDelivery,
    DateTime? ActualDelivery,
    string? CustomerEmail);

public record ShipmentUpdateDto(int Id, string Status, DateTime? EstimatedDelivery);

public interface IShipmentService
{
    Task<List<ShipmentDto>> GetAllShipmentsAsync();
    Task<ShipmentDto?> TrackShipmentAsync(string trackingNumber);
    Task UpdateShipmentAsync(ShipmentUpdateDto update);
}

using System.Net.Http.Json;

namespace ShipmentTracker.Client.Services;

public class ShipmentHttpService(HttpClient http) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments") ?? [];
    }

    public async Task<ShipmentDto?> TrackShipmentAsync(string trackingNumber)
    {
        var response = await http.GetAsync($"api/shipments/track/{trackingNumber}");
        if (!response.IsSuccessStatusCode)
            return null;
        return await response.Content.ReadFromJsonAsync<ShipmentDto>();
    }

    public async Task UpdateShipmentAsync(ShipmentUpdateDto update)
    {
        await http.PutAsJsonAsync($"api/shipments/{update.Id}", update);
    }
}

