using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await db.Shipments
            .OrderByDescending(s => s.ShippedDate)
            .Select(s => new ShipmentDto(
                s.Id, s.TrackingNumber, s.Origin, s.Destination,
                s.Status, s.ShippedDate, s.EstimatedDelivery,
                s.ActualDelivery, s.CustomerEmail))
            .ToListAsync();
    }

    public async Task<ShipmentDto?> TrackShipmentAsync(string trackingNumber)
    {
        var s = await db.Shipments
            .FirstOrDefaultAsync(x => x.TrackingNumber == trackingNumber);
        if (s is null) return null;
        return new ShipmentDto(s.Id, s.TrackingNumber, s.Origin, s.Destination,
            s.Status, s.ShippedDate, s.EstimatedDelivery, s.ActualDelivery, s.CustomerEmail);
    }

    public async Task UpdateShipmentAsync(ShipmentUpdateDto update)
    {
        var shipment = await db.Shipments.FindAsync(update.Id);
        if (shipment is null) return;

        shipment.Status = update.Status;
        shipment.EstimatedDelivery = update.EstimatedDelivery;

        if (update.Status == "Delivered" && shipment.ActualDelivery is null)
            shipment.ActualDelivery = DateTime.UtcNow;

        await db.SaveChangesAsync();
    }
}

