 // Add additional endpoints required by the Identity /Account Razor components.
 app.MapAdditionalIdentityEndpoints();

+// Shipment API endpoints
+var shipments = app.MapGroup("api/shipments").RequireAuthorization();
+
+shipments.MapGet("/", async (IShipmentService svc) =>
+    Results.Ok(await svc.GetAllShipmentsAsync()));
+
+shipments.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService svc) =>
+{
+    var result = await svc.TrackShipmentAsync(trackingNumber);
+    return result is not null ? Results.Ok(result) : Results.NotFound();
+});
+
+shipments.MapPut("/{id}", async (int id, ShipmentUpdateDto update, IShipmentService svc) =>
+{
+    await svc.UpdateShipmentAsync(update with { Id = id });
+    return Results.NoContent();
+});
+
 app.Run();

